<?php
namespace Modules\Glitter\Analytics\Repositories;
use Carbon\CarbonImmutable; use Illuminate\Database\Eloquent\Builder; use Illuminate\Pagination\LengthAwarePaginator; use Illuminate\Support\Collection; use Modules\Glitter\Analytics\DTO\AnalyticsVisitFilter; use Modules\Glitter\Analytics\DTO\CreateAnalyticsEventData; use Modules\Glitter\Analytics\Enums\AnalyticsEventType; use Modules\Glitter\Analytics\Models\AnalyticsEvent; use Modules\Glitter\Analytics\Repositories\Contracts\AnalyticsEventRepositoryInterface; use Illuminate\Support\Facades\Schema;
class AnalyticsEventRepository implements AnalyticsEventRepositoryInterface {
 public function create(CreateAnalyticsEventData $d):AnalyticsEvent{return AnalyticsEvent::query()->create($d->toArray());}
 public function findLatestBySessionHash(string $h):?AnalyticsEvent{return AnalyticsEvent::query()->where('session_hash',$h)->orderByDesc('occurred_at')->orderByDesc('id')->first();}
 public function clearUserReference(int $id):int{return AnalyticsEvent::query()->where('user_id',$id)->update(['user_id'=>null]);}
 public function deleteOlderThan(CarbonImmutable $c,int $l):int{if($l<1)return 0;$ids=AnalyticsEvent::query()->where('occurred_at','<',$c)->orderBy('occurred_at')->orderBy('id')->limit($l)->pluck('id');return $ids->isEmpty()?0:AnalyticsEvent::query()->whereIn('id',$ids)->delete();}
 public function countOlderThan(CarbonImmutable $c):int{return AnalyticsEvent::query()->where("occurred_at","<",$c)->count();}
 public function paginateVisits(AnalyticsVisitFilter $f):LengthAwarePaginator{return $this->visits($f)->paginate($f->perPage,['*'],'page',$f->page);}
 public function cursorVisits(AnalyticsVisitFilter $f):\Illuminate\Support\LazyCollection{return $this->visits($f)->cursor();}
 public function recentVisits(AnalyticsVisitFilter $f,int $limit):Collection{return $this->visits($f)->limit($limit)->get();}
 public function summary(AnalyticsVisitFilter $f,CarbonImmutable $today):array{$r=$this->base($f)->selectRaw('COUNT(*) AS pageviews_7d, SUM(CASE WHEN occurred_at >= ? THEN 1 ELSE 0 END) AS pageviews_today, COUNT(DISTINCT CASE WHEN occurred_at >= ? THEN visitor_hash END) AS visitors_today, COUNT(DISTINCT CASE WHEN occurred_at >= ? THEN session_hash END) AS sessions_today',[$today,$today,$today])->first();return ['visitors_today'=>(int)($r->visitors_today??0),'sessions_today'=>(int)($r->sessions_today??0),'pageviews_today'=>(int)($r->pageviews_today??0),'pageviews_7d'=>(int)($r->pageviews_7d??0)];}
 public function dailyTrend(array $days):array{$q=$this->baseRange($days[0]['from'],$days[count($days)-1]['to']);$select=[];$bindings=[];foreach($days as $i=>$d){$select[]="SUM(CASE WHEN occurred_at >= ? AND occurred_at < ? THEN 1 ELSE 0 END) AS p{$i}";$bindings[]=$d['from'];$bindings[]=$d['to'];$select[]="COUNT(DISTINCT CASE WHEN occurred_at >= ? AND occurred_at < ? THEN visitor_hash END) AS v{$i}";$bindings[]=$d['from'];$bindings[]=$d['to'];}$r=$q->selectRaw(implode(',',$select),$bindings)->first();return array_map(fn($d,$i)=>['date'=>$d['date'],'pageviews'=>(int)($r->{"p{$i}"}??0),'visitors'=>(int)($r->{"v{$i}"}??0)],$days,array_keys($days));}
 public function popularPaths(AnalyticsVisitFilter $f,int $limit):array{return $this->base($f)->selectRaw("SUBSTRING_INDEX(SUBSTRING_INDEX(path, '?', 1), '#', 1) AS path, COUNT(*) AS pageviews")->groupByRaw("SUBSTRING_INDEX(SUBSTRING_INDEX(path, '?', 1), '#', 1)")->orderByDesc('pageviews')->orderBy('path')->limit($limit)->get()->map(fn($r)=>['path'=>$r->path,'pageviews'=>(int)$r->pageviews])->all();}
 public function topReferrers(AnalyticsVisitFilter $f,int $limit,?string $host):array{$q=$this->base($f)->whereNotNull('referrer_host')->where('referrer_host','<>','');if($host)$q->where('referrer_host','<>',strtolower($host));return $q->selectRaw('referrer_host, COUNT(*) AS pageviews')->groupBy('referrer_host')->orderByDesc('pageviews')->orderBy('referrer_host')->limit($limit)->get()->map(fn($r)=>['host'=>$r->referrer_host,'pageviews'=>(int)$r->pageviews])->all();}
 private function visits(AnalyticsVisitFilter $f):Builder{$q=$this->base($f)->leftJoin('users as analytics_user','analytics_user.id','=','analytics_events.user_id')->select(['analytics_events.id','analytics_events.occurred_at','analytics_events.path','analytics_events.source','analytics_events.user_id','analytics_user.name as user_name','analytics_events.visitor_hash','analytics_events.session_hash','analytics_events.referrer_host'])->orderByDesc('analytics_events.occurred_at')->orderByDesc('analytics_events.id');if($f->path){$term=addcslashes($f->path,'\%_');$q->where('analytics_events.path','like','%'.$term.'%');}if($f->source)$q->where('analytics_events.source',$f->source);if($f->member==='member')$q->whereNotNull('analytics_events.user_id');if($f->member==='guest')$q->whereNull('analytics_events.user_id');return $q;}
 private function base(AnalyticsVisitFilter $f):Builder{return $this->baseRange($f->fromUtc,$f->toUtc);}
 private function baseRange(CarbonImmutable $from,CarbonImmutable $to):Builder{return AnalyticsEvent::query()->where('event_type',AnalyticsEventType::PageView->value)->where('occurred_at','>=',$from)->where('occurred_at','<',$to)->where('path','like','/%')->where('path','not like','//%')->where('path','not like','/admin%')->where('path','not like','/api%')->where('path','not like','/build%');}
}
